/**
 * KS-1013 — PATCH /api/users/admin/:id answers 400 for a malformed id.
 *
 * The route never validated the `{id}` FORMAT, so a non-UUID reached Postgres,
 * raised `22P02 invalid input syntax for type uuid` inside `getUserById` (via
 * the one-line `getUserByIdPlatformScope` wrapper) and propagated as a raw 500.
 *
 * ⚠ KS-963 (`561de81ca`) is CONTEXT, NOT CAUSE, and blame output will point at
 * it. That ruling made `getUserById` rethrow instead of swallowing DB errors as
 * `null`; before it, this same malformed id produced a 404 — which was ALSO a
 * wrong answer, because it told the caller "user not found" about an id that
 * could never name a user in any tenant. KS-963 removed the swallow that was
 * hiding this gap. **Do not revert it to make this route quiet.**
 *
 * The three cells are s153's, re-run here as executable assertions. Two
 * necessary conditions: the failure needs BOTH a malformed id AND an updatable
 * field, because the "no valid fields to update" check short-circuits first.
 *
 *   REPRO      id=0 + body {organizationId}  ->  was 500, now 400
 *   CONTROL A  well-formed UUID + same body  ->  404, unchanged
 *   CONTROL B  id=0 + empty body {}          ->  400, unchanged
 *
 * Controls A and B are what make the REPRO mean something: without them a 400
 * on every request would satisfy the repro cell just as well.
 *
 * The repo is mocked, so this suite cannot observe 22P02 itself — it asserts
 * the guard SHORT-CIRCUITS BEFORE the lookup, which is the property that keeps
 * a malformed id away from Postgres. `getUserByIdPlatformScope` not being
 * called is therefore a load-bearing assertion, not decoration.
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach, vi } from 'vitest';
import type { AddressInfo } from 'node:net';
import type { Server } from 'node:http';
import express from 'express';

const KNOWN_USER = 'aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa';
const UNKNOWN_BUT_WELL_FORMED = 'eeeeeeee-5555-4555-8555-eeeeeeeeeeee';

const state = vi.hoisted(() => ({
  caller: { userId: 'dddddddd-4444-4444-8444-dddddddddddd', role: 'SYSTEM_ADMIN', tenantId: 'tenant-default' },
  users: new Map<string, Record<string, unknown>>(),
}));

// The repo mock answers null for anything unseeded. That is deliberately the
// FORGIVING behaviour — real Postgres raises 22P02 on a non-UUID rather than
// returning no rows — so any cell that reaches this mock with a malformed id
// would go green over the live defect. The guard must run first.
const repoMock = vi.hoisted(() => ({
  getUserById: vi.fn(async (id: string) => state.users.get(id) ?? null),
  getUserByIdPlatformScope: vi.fn(async (id: string) => state.users.get(id) ?? null),
  updateUser: vi.fn(async () => null),
  updateUserPlatformScope: vi.fn(async (id: string, updates: Record<string, unknown>) => {
    const existing = state.users.get(id);
    if (!existing) return null;
    const merged = { ...existing, ...updates };
    state.users.set(id, merged);
    return merged;
  }),
  listUsers: vi.fn(async () => []),
  countUsers: vi.fn(async () => 0),
  listOrganizations: vi.fn(async () => []),
  getOrganizationTenant: vi.fn(async () => ({ tenantId: 'tenant-default' })),
  emailExists: vi.fn(async () => false),
  createUser: vi.fn(async (user: Record<string, unknown>) => user),
}));
vi.mock('../repositories/userRepo', () => repoMock);

vi.mock('../middleware/authenticate', () => {
  const injectCaller =
    () => (req: express.Request & { user?: unknown }, _res: express.Response, next: express.NextFunction) => {
      (req as { user: unknown }).user = { ...state.caller };
      next();
    };
  return { authenticate: injectCaller, authenticateAccessOrConnector: injectCaller };
});

vi.mock('../db', () => ({ isDbAvailable: () => false, query: vi.fn(async () => ({ rows: [] })) }));
vi.mock('../services/session', () => ({ revokeAllUserSessions: vi.fn(async () => 0) }));
vi.mock('../services/password', () => ({
  hashPassword: vi.fn(async () => 'hashed'),
  checkPasswordStrength: vi.fn(() => ({ ok: true })),
  verifyPassword: vi.fn(async () => true),
}));
vi.mock('../utils/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}));

import { userRoutes } from '../routes/users';
import { errorHandler } from '../middleware/errorHandler';

let server: Server;
let baseUrl: string;

beforeAll(async () => {
  const app = express();
  app.use(express.json());
  app.use('/', userRoutes);
  app.use(errorHandler);
  await new Promise<void>((resolve) => {
    // KS-860: bind an explicit host — `listen(0, <function>)` passes the
    // callback as the host and binds every interface.
    server = app.listen(0, '127.0.0.1', () => {
      const { port } = server.address() as AddressInfo;
      baseUrl = `http://127.0.0.1:${port}`;
      resolve();
    });
  });
});

afterAll(async () => {
  await new Promise<void>((resolve) => server.close(() => resolve()));
});

beforeEach(() => {
  vi.clearAllMocks();
  state.users.clear();
  state.users.set(KNOWN_USER, {
    id: KNOWN_USER,
    email: 'a@tenant-a.example',
    role: 'USER',
    status: 'ACTIVE',
    verificationLevel: 'BASIC',
    tenantId: 'tenant-default',
  });
  state.caller = { userId: 'dddddddd-4444-4444-8444-dddddddddddd', role: 'SYSTEM_ADMIN', tenantId: 'tenant-default' };
});

async function patchUser(id: string, body: unknown): Promise<globalThis.Response> {
  return fetch(`${baseUrl}/admin/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

describe('KS-1013 — a malformed {id} is refused before the lookup', () => {
  it('REPRO: id=0 with an updatable field is 400, not 500', async () => {
    const res = await patchUser('0', { organizationId: 'e3e70682-c209-1cac-a29f-6fbed82c07cd' });
    expect(res.status).toBe(400);
    const body = await res.json();
    expect(body.error.code).toBe('BAD_REQUEST');
    // The property that keeps 22P02 away from the top: the lookup never ran.
    expect(repoMock.getUserByIdPlatformScope).not.toHaveBeenCalled();
    expect(repoMock.updateUserPlatformScope).not.toHaveBeenCalled();
  });

  it('CONTROL A: a well-formed but unknown id still answers 404, unchanged', async () => {
    const res = await patchUser(UNKNOWN_BUT_WELL_FORMED, {
      organizationId: 'e3e70682-c209-1cac-a29f-6fbed82c07cd',
    });
    expect(res.status).toBe(404);
    // The guard let this one through — the 404 comes from the lookup, so the
    // new check cannot be answering 400 for everything.
    expect(repoMock.getUserByIdPlatformScope).toHaveBeenCalledWith(UNKNOWN_BUT_WELL_FORMED);
  });

  it('CONTROL B: id=0 with an EMPTY body is 400 from the no-fields check, unchanged', async () => {
    const res = await patchUser('0', {});
    expect(res.status).toBe(400);
    const body = await res.json();
    // Distinct message from the REPRO cell: the no-valid-fields check still
    // short-circuits first, so the guard did not move that behaviour.
    expect(body.error.message).toBe('No valid fields to update');
    expect(repoMock.getUserByIdPlatformScope).not.toHaveBeenCalled();
  });

  it('a well-formed id that EXISTS still updates — the guard refuses only the malformed', async () => {
    const res = await patchUser(KNOWN_USER, { displayName: 'renamed' });
    expect(res.status).toBe(200);
    expect(repoMock.updateUserPlatformScope).toHaveBeenCalledWith(KNOWN_USER, { displayName: 'renamed' });
  });

  it.each([
    ['a bare integer', '0'],
    ['a word', 'nope'],
    ['a truncated uuid', 'aaaaaaaa-1111-4111-8111-aaaaaaaaaaa'],
    ['a uuid with a trailing suffix', 'aaaaaaaa-1111-4111-8111-aaaaaaaaaaaa-x'],
    ['a percent-encoded NUL byte', '%00'],
    ['a non-ascii id', 'ééé'],
  ])('refuses %s with 400 and never reaches the repo', async (_label, id) => {
    const res = await patchUser(id, { displayName: 'x' });
    expect(res.status).toBe(400);
    expect(repoMock.getUserByIdPlatformScope).not.toHaveBeenCalled();
  });
});
